/* @lc app=leetcode id=3926 lang=kotlin */ class Solution { fun countWordOccurrences(chunks: Array<String>, queries: Array<String>): IntArray = chunks.joinToString("").let { s -> s.indices.map { i -> if (s[i] in 'a'..'z' || (s[i] == '-' && i > 0 && i < s.length - 1 && s[i - 1] in 'a'..'z' && s[i + 1] in 'a'..'z')) s[i] else ' ' }.joinToString("").split(" ").filter { it.isNotEmpty() }.groupingBy { it }.eachCount().let { c -> queries.map { c[it] ?: 0 }.toIntArray() } } }